<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount,onMounted} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {useWorkbench} from '../stores/workbench'
import {uid} from '../lib/domain'
import {emptyVisualWorkbench,mediaKind,type VisualNeed,type VisualCandidate,type VisualPlacement,type MediaKind} from '../lib/visual-candidates'
import Icon from '../components/Icon.vue'
import Dialog from '../components/Dialog.vue'
import VisualPreview from '../components/VisualPreview.vue'
import VisualGenerationPanel from '../components/VisualGenerationPanel.vue'

const store=useWorkbench(),route=useRoute(),router=useRouter()
const projectId=ref(String(route.query.projectId??'')),needId=ref(String(route.query.need??route.query.shot??'')),search=ref('')
const project=computed(()=>store.state.projects.find(p=>p.id===projectId.value)),workbench=computed(()=>project.value?.visualWorkbench??emptyVisualWorkbench())
const productionFilter=ref(['N27','N29'].includes(String(route.query.node))?String(route.query.node):'')
const needs=computed(()=>workbench.value.needs.filter(n=>(n.title+n.description).includes(search.value)&&(!productionFilter.value||(productionFilter.value==='UNASSIGNED'?!n.productionNodeId:n.productionNodeId===productionFilter.value))))
const need=computed(()=>needs.value.find(n=>n.id===needId.value)??needs.value[0])
const batches=computed(()=>workbench.value.batches.filter(b=>b.needId===need.value?.id).slice().reverse())
const batchId=ref(''),filter=ref('ALL'),compare=ref<string[]>([]),urls=ref<Record<string,string>>({}),durations=ref<Record<string,number>>({}),busy=ref(false)
const activePlacements=computed(()=>workbench.value.placements.filter(p=>p.active)),needPlacements=computed(()=>activePlacements.value.filter(p=>p.needId===need.value?.id))
const candidates=computed(()=>workbench.value.candidates.filter(c=>c.needId===need.value?.id&&(!batchId.value||c.batchId===batchId.value)&&(filter.value==='ALL'||(filter.value==='USED'?used(c):c.status===filter.value))).slice().reverse())
const compared=computed(()=>compare.value.map(id=>workbench.value.candidates.find(c=>c.id===id)).filter((c):c is VisualCandidate=>!!c))
const history=computed(()=>workbench.value.placements.filter(p=>p.needId===need.value?.id).slice().reverse())
const statusNames={PENDING:'待选',KEPT:'已保留',REJECTED:'已淘汰'},referenceNames:Record<string,string>={GENERAL:'一般参考',FIRST_FRAME:'首帧参考',LAST_FRAME:'尾帧参考',CHARACTER:'人物参考',STYLE:'风格参考'}
const money=(cents:number)=>(cents/100).toFixed(2),seconds=(ms?:number)=>((ms??0)/1000).toFixed(3).replace(/\.?0+$/,'')||'0'
const asset=(c:VisualCandidate)=>store.state.assets.find(a=>a.id===c.assetId),batch=(c:VisualCandidate)=>workbench.value.batches.find(b=>b.id===c.batchId)
const used=(c:VisualCandidate)=>activePlacements.value.filter(p=>p.candidateId===c.id).length
const candidate=(p:VisualPlacement)=>workbench.value.candidates.find(c=>c.id===p.candidateId)
const location=(p:VisualPlacement)=>p.purpose==='REFERENCE'?referenceNames[p.referenceRole??'GENERAL']:`${p.trackId} · ${seconds(p.targetStartMs)}–${seconds(p.targetEndMs)} 秒`
async function command(type:string,payload:Record<string,unknown>,message:string){return await store.command({type,payload:{projectId:projectId.value,...payload}},message)}
function context(){needId.value='';compare.value=[];batchId.value='';router.replace({query:{projectId:projectId.value}})}
function chooseNeed(id:string){needId.value=id;compare.value=[];batchId.value='';router.replace({query:{...route.query,need:id}})}
watch(()=>need.value?.id,()=>{compare.value=[];batchId.value=''})
let epoch=0,disposed=false
function revoke(values:Record<string,string>){for(const url of Object.values(values))if(url.startsWith('blob:'))URL.revokeObjectURL(url)}
watch(()=>workbench.value.candidates.map(c=>c.assetId).join('|'),async()=>{
 const current=++epoch,next:Record<string,string>={}
 for(const c of workbench.value.candidates){const a=asset(c);if(a)try{next[c.id]=await store.assetUrl({...a,fileRef:c.fileRef})}catch{}}
 if(disposed||current!==epoch){revoke(next);return}const old=urls.value;urls.value=next;setTimeout(()=>revoke(old),0)
},{immediate:true})
const needOpen=ref(false),editingNeed=ref(''),title=ref(''),description=ref(''),productionNodeId=ref<'N27'|'N29'>('N27'),shotId=ref(''),hasRange=ref(false),desiredStart=ref(0),desiredEnd=ref(3)
function editNeed(value?:VisualNeed){editingNeed.value=value?.id??'';title.value=value?.title??'';description.value=value?.description??'';productionNodeId.value=value?.productionNodeId??(productionFilter.value==='N29'?'N29':'N27');shotId.value=value?.shotId??'';hasRange.value=value?.desiredStartMs!==undefined;desiredStart.value=(value?.desiredStartMs??0)/1000;desiredEnd.value=(value?.desiredEndMs??3000)/1000;needOpen.value=true}
async function saveNeed(){const id=editingNeed.value||uid('need');if(await command(editingNeed.value?'UPDATE_VISUAL_NEED':'CREATE_VISUAL_NEED',{...(editingNeed.value?{needId:id}:{id}),title:title.value,description:description.value,productionNodeId:productionNodeId.value,shotId:shotId.value,...(hasRange.value?{desiredStartMs:Math.round(desiredStart.value*1000),desiredEndMs:Math.round(desiredEnd.value*1000)}:{})},'画面需求已保存')){needOpen.value=false;needId.value=id;productionFilter.value=productionNodeId.value;router.replace({query:{projectId:projectId.value,need:id}})}}
async function removeEmpty(){if(need.value&&window.confirm('删除这个尚无批次的画面需求？')){if(await command('REMOVE_EMPTY_VISUAL_NEED',{needId:need.value.id},'空需求已删除'))needId.value=''}}
const referenceId=ref(''),referenceRoleForBatch=ref('FIRST_FRAME')
const referenceCandidates=computed(()=>workbench.value.candidates.filter(c=>c.mediaKind==='IMAGE'&&c.status!=='REJECTED'))
const batchOpen=ref(false),batchKind=ref<MediaKind>('VIDEO'),prompt=ref(''),externalModel=ref(''),modelId=ref(''),parameters=ref('{}'),budget=ref(0),sourceBatchId=ref('')
const models=computed(()=>store.state.models.filter(m=>m.capabilities.includes(batchKind.value==='IMAGE'?'IMAGE_GENERATION':'VIDEO_GENERATION')))
watch(batchKind,()=>{if(batchKind.value==='IMAGE')referenceId.value='';if(!models.value.some(m=>m.id===modelId.value))modelId.value=''})
function newBatch(source=''){const old=workbench.value.batches.find(b=>b.id===source);sourceBatchId.value=source;batchKind.value=old?.mediaKind??'VIDEO';prompt.value=old?.prompt??need.value?.description??'';externalModel.value=old?.modelSnapshot.name??'';modelId.value=models.value.some(m=>m.id===old?.modelSnapshot.id)?old!.modelSnapshot.id:'';parameters.value=JSON.stringify(old?.parameters??{},null,2);referenceId.value=old?.references?.[0]?.candidateId??'';referenceRoleForBatch.value=old?.references?.[0]?.role??'FIRST_FRAME';budget.value=(old?.budgetCents??0)/100;batchOpen.value=true}
async function saveBatch(){if(!need.value)return;try{const id=uid('batch');if(await command('CREATE_VISUAL_BATCH',{id,needId:need.value.id,mediaKind:batchKind.value,prompt:prompt.value,externalModel:externalModel.value,modelId:modelId.value,parameters:JSON.parse(parameters.value),budgetCents:Math.round(budget.value*100),references:batchKind.value==='VIDEO'&&referenceId.value?[{candidateId:referenceId.value,role:referenceRoleForBatch.value}]:[],...(sourceBatchId.value?{sourceBatchId:sourceBatchId.value}:{})},'候选批次已保存')){batchId.value=id;batchOpen.value=false}}catch{store.toast('参数必须为有效 JSON 对象','error')}}
const importOpen=ref(false),importBatchId=ref(''),seed=ref(''),cost=ref(0),note=ref(''),files=ref<File[]>([]),results=ref<string[]>([]),libraryAssetId=ref('')
const importBatch=computed(()=>batches.value.find(b=>b.id===importBatchId.value)),libraryAssets=computed(()=>store.state.assets.filter(a=>a.projectId===projectId.value&&mediaKind(a.type)===importBatch.value?.mediaKind))
function newImport(){importBatchId.value=batchId.value||batches.value[0]?.id||'';seed.value='';cost.value=0;note.value='';files.value=[];results.value=[];importOpen.value=true}
function pickFiles(event:Event){files.value=Array.from((event.target as HTMLInputElement).files??[])}
async function duration(file:File):Promise<number|undefined>{if(mediaKind(file.type)!=='VIDEO')return;const url=URL.createObjectURL(file),v=document.createElement('video');return await new Promise(resolve=>{const finish=(value?:number)=>{clearTimeout(timer);v.removeAttribute('src');v.load();URL.revokeObjectURL(url);resolve(value)};const timer=setTimeout(()=>finish(),4000);v.onloadedmetadata=()=>finish(Number.isFinite(v.duration)&&v.duration>0?Math.round(v.duration*1000):undefined);v.onerror=()=>finish();v.preload='metadata';v.src=url})}
async function importFiles(){if(!project.value)return;busy.value=true;results.value=[];const remaining:File[]=[]
 try{for(const raw of files.value){const extension=raw.name.split('.').pop()?.toLowerCase(),type=({mp4:'video/mp4',webm:'video/webm',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'} as Record<string,string>)[extension??''];if(!raw.size||raw.size>50*1024*1024||!type||mediaKind(type)!==importBatch.value?.mediaKind){results.value.push(raw.name+'：文件类型不匹配或超过 50MB');remaining.push(raw);continue}
  const file=new File([raw],raw.name,{type}),durationMs=await duration(file),uploaded=await store.addAsset(file,project.value.id)
  if(!uploaded){results.value.push(raw.name+'：上传失败');remaining.push(raw);continue}
  if(await command('IMPORT_VISUAL_CANDIDATE',{id:uid('candidate'),batchId:importBatchId.value,assetId:uploaded.id,seed:seed.value,costCents:Math.round(cost.value*100),note:note.value,...(durationMs?{durationMs}:{})},'候选已导入'))results.value.push(raw.name+'：导入成功');else results.value.push(raw.name+'：登记失败，原件已保留在素材库')
 }files.value=remaining}finally{busy.value=false}}
async function importExisting(){if(await command('IMPORT_VISUAL_CANDIDATE',{id:uid('candidate'),batchId:importBatchId.value,assetId:libraryAssetId.value,seed:seed.value,costCents:Math.round(cost.value*100),note:note.value},'现有素材已登记'))results.value.push('现有素材登记成功')}
async function status(c:VisualCandidate,value:string){await command('SET_VISUAL_CANDIDATE_STATUS',{candidateId:c.id,status:value},'候选状态已更新')}
function toggleCompare(id:string){if(compare.value.includes(id))compare.value=compare.value.filter(x=>x!==id);else if(compare.value.length<2)compare.value.push(id);else store.toast('请先移除一条对比候选','error')}
const adoptOpen=ref(false),adoption=ref<VisualCandidate>(),purpose=ref<'TIMELINE'|'REFERENCE'>('TIMELINE'),referenceRole=ref('GENERAL'),trackId=ref('V1'),sourceIn=ref(0),sourceOut=ref(0),sourceDuration=ref(0),targetStart=ref(0),targetEnd=ref(3),reason=ref(''),replacesId=ref('')
watch([targetStart,sourceIn,sourceOut],()=>{if(adoption.value?.mediaKind==='VIDEO')targetEnd.value=Math.round((targetStart.value+sourceOut.value-sourceIn.value)*1000)/1000})
function metadata(id:string,ms:number){durations.value[id]=ms;if(adoptOpen.value&&adoption.value?.id===id&&!sourceDuration.value){sourceDuration.value=ms/1000;sourceOut.value=Math.min(3,ms/1000)}}
function requestAdopt(c:VisualCandidate,replace?:VisualPlacement){adoption.value=c;purpose.value=replace?.purpose??(c.mediaKind==='IMAGE'?'REFERENCE':'TIMELINE');referenceRole.value=replace?.referenceRole??'GENERAL';trackId.value=replace?.trackId??'V1';sourceDuration.value=(c.durationMs??durations.value[c.id]??0)/1000;sourceIn.value=replace?.candidateId===c.id?(replace.sourceInMs??0)/1000:0;sourceOut.value=replace?.candidateId===c.id?(replace.sourceOutMs??0)/1000:Math.min(sourceDuration.value,(need.value?.desiredEndMs??3000)/1000-(need.value?.desiredStartMs??0)/1000);targetStart.value=(replace?.targetStartMs??need.value?.desiredStartMs??0)/1000;targetEnd.value=(replace?.targetEndMs??need.value?.desiredEndMs??3000)/1000;reason.value='';replacesId.value=replace?.id??'';adoptOpen.value=true}
function replacement(){const old=needPlacements.value.find(p=>p.id===replacesId.value);if(!old)return;purpose.value=old.purpose;referenceRole.value=old.referenceRole??'GENERAL';trackId.value=old.trackId??'V1';targetStart.value=(old.targetStartMs??0)/1000;targetEnd.value=(old.targetEndMs??3000)/1000;if(adoption.value?.mediaKind==='VIDEO'){sourceIn.value=0;sourceOut.value=Math.min(sourceDuration.value,targetEnd.value-targetStart.value)}}
async function adopt(){if(!adoption.value)return;const ms=(s:number)=>Math.round(s*1000);if(await command('ADOPT_VISUAL_CANDIDATE',{id:uid('placement'),candidateId:adoption.value.id,purpose:purpose.value,reason:reason.value,...(purpose.value==='TIMELINE'?{targetStartMs:ms(targetStart.value),targetEndMs:ms(targetEnd.value),trackId:trackId.value}:{referenceRole:referenceRole.value}),...(adoption.value.mediaKind==='VIDEO'?{sourceInMs:ms(sourceIn.value),sourceOutMs:ms(sourceOut.value),sourceDurationMs:ms(sourceDuration.value)}:{}),...(replacesId.value?{replacesId:replacesId.value}:{})},'采用决定已记录；制作步骤需单独验收'))adoptOpen.value=false}
const removeOpen=ref(false),removing=ref<VisualPlacement>(),removeReason=ref('')
function requestRemove(p:VisualPlacement){removing.value=p;removeReason.value='';removeOpen.value=true}
async function removePlacement(){if(removing.value&&await command('REMOVE_VISUAL_PLACEMENT',{placementId:removing.value.id,reason:removeReason.value},'已撤销采用，历史和原文件保留'))removeOpen.value=false}
function exportPlan(){if(!project.value)return;const plan={schemaVersion:3,projectId:project.value.id,revision:workbench.value.revision,needs:workbench.value.needs,placements:activePlacements.value,candidates:workbench.value.candidates.filter(c=>activePlacements.value.some(p=>p.candidateId===c.id))};const url=URL.createObjectURL(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='visual-plan-'+project.value.id+'.json';a.click();URL.revokeObjectURL(url)}
const openForm=computed(()=>needOpen.value||batchOpen.value||importOpen.value||adoptOpen.value||removeOpen.value)
onBeforeRouteLeave(()=>{if(busy.value){store.toast('请等待素材导入完成','error');return false}return !openForm.value||window.confirm('有尚未提交的画面资料，确定放弃并离开？')})
function unload(event:BeforeUnloadEvent){if(openForm.value||busy.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',unload));onBeforeUnmount(()=>{disposed=true;epoch++;revoke(urls.value);window.removeEventListener('beforeunload',unload)})
</script>

<template><div class="page-content video-workbench">
 <div class="page-heading"><div><h1>画面抽卡</h1><p>为主体内容和辅助画面抽取候选，选好后交给剪辑。</p></div><button class="btn primary" :disabled="!project" @click="editNeed()"><Icon name="Plus"/>新建画面需求</button></div>
 <div class="candidate-context"><label>作品<select v-model="projectId" aria-label="作品" @change="context"><option value="">选择作品</option><option v-for="p in store.state.projects" :key="p.id" :value="p.id">{{p.title}}</option></select></label><label>制作任务<select v-model="productionFilter" aria-label="制作任务筛选"><option value="">全部制作任务</option><option value="N27">主体内容 · N27</option><option value="N29">辅助画面 · N29</option><option value="UNASSIGNED">旧需求 · 待归类</option></select></label><label>查找画面需求<input v-model="search" placeholder="表情、开场、12 秒…"></label><p>画面需求归属视频制作任务；支持远程执行接口和手工导入。成片任意时间区间都可单独选片。</p></div>
 <div v-if="!project" class="empty-state"><Icon name="Images" :size="40"/><h2>先选择作品，再描述你想要的画面</h2><p>可以先选参考图，也可以直接优化视频中的某个时间区间。</p></div>
 <template v-else>
  <p v-if="workbench.legacyAdoptions.length" class="candidate-notice">已保留旧版镜头、候选和采用历史；旧的整段采用未被猜测成时间区间，请按需要重新指定采用位置。</p>
  <div class="candidate-layout"><aside class="shot-list" aria-label="画面需求列表"><h2>画面需求 <span>{{needs.length}}</span></h2><button v-for="n in needs" :key="n.id" :class="['shot-row',{active:n.id===need?.id}]" @click="chooseNeed(n.id)"><b>{{n.title}}</b><small>{{n.desiredStartMs!==undefined?seconds(n.desiredStartMs)+'–'+seconds(n.desiredEndMs)+' 秒':'位置待定 / 参考画面'}}</small></button></aside>
   <section v-if="need" class="candidate-content"><div class="candidate-heading"><div><h2>{{need.title}}</h2><p>{{need.description||'先收集候选，再决定怎样使用。'}}</p><p>{{need.productionNodeId==='N27'?'主体内容 · N27':need.productionNodeId==='N29'?'辅助画面 · N29':'旧需求待归类，请编辑归属'}} · 采用 {{needPlacements.length}} 处</p></div><div class="heading-actions"><button class="btn" @click="editNeed(need)">编辑需求</button><button class="btn" :disabled="!!batches.length" @click="removeEmpty">删除空需求</button><button class="btn" @click="newBatch()">新建候选批次</button><button class="btn primary" :disabled="!batches.length" @click="newImport"><Icon name="Upload"/>导入候选</button></div></div>
    <VisualGenerationPanel :key="project.id+need.id" :project-id="project.id" :need="need" :batches="batches"/><div class="candidate-filters"><label>批次<select v-model="batchId" aria-label="批次"><option value="">全部批次</option><option v-for="(b,i) in batches" :key="b.id" :value="b.id">第 {{batches.length-i}} 批 · {{b.mediaKind==='IMAGE'?'图片':'视频'}} · {{b.modelSnapshot.name}}</option></select></label><label>状态<select v-model="filter" aria-label="候选状态"><option value="ALL">全部候选</option><option value="PENDING">待选</option><option value="KEPT">已保留</option><option value="REJECTED">已淘汰</option><option value="USED">正在使用</option></select></label></div>
    <div v-if="compared.length" class="compare-panel"><div class="section-heading"><h3>候选对比 · {{compared.length}} / 2</h3><button class="text-link" @click="compare=[]">清空对比</button></div><div class="compare-grid"><article v-for="c in compared" :key="c.id"><VisualPreview :src="urls[c.id]??''" :kind="c.mediaKind" :label="asset(c)?.name??'候选'" @metadata="ms=>metadata(c.id,ms)"/><b>{{asset(c)?.name}}</b><p>{{c.mediaKind==='IMAGE'?'图片':'视频'}} · seed {{c.seed||'未记录'}}</p></article></div></div>
    <div class="video-candidate-grid"><article v-for="c in candidates" :key="c.id" :class="['video-candidate',{adopted:used(c)}]" :data-candidate-id="c.id"><VisualPreview :src="urls[c.id]??''" :kind="c.mediaKind" :label="asset(c)?.name??'候选'" @metadata="ms=>metadata(c.id,ms)"/><div class="candidate-description"><div class="candidate-name"><h3>{{asset(c)?.name}}</h3><span class="badge neutral">{{used(c)?'已用 '+used(c)+' 处':statusNames[c.status]}}</span></div><p>{{c.mediaKind==='IMAGE'?'图片':'视频'}} · {{batch(c)?.modelSnapshot.name}} · seed {{c.seed||'未记录'}} · ¥{{money(c.costCents)}}</p><details><summary>提示词与生成记录</summary><p>{{batch(c)?.prompt}}</p><p v-for="ref in batch(c)?.references" :key="ref.candidateId">参考：{{workbench.candidates.find(x=>x.id===ref.candidateId)?asset(workbench.candidates.find(x=>x.id===ref.candidateId)!)?.name:ref.candidateId}} · {{referenceNames[ref.role]}}</p><pre>{{JSON.stringify(batch(c)?.parameters,null,2)}}</pre><p class="file-checksum">SHA-256 {{c.sha256}}</p><a v-if="urls[c.id]" class="text-link" :href="urls[c.id]" :download="asset(c)?.name">下载原件</a><button class="text-link" @click="newBatch(c.batchId)">沿用设置建立下一批</button></details><div class="video-candidate-actions"><button class="btn" :aria-pressed="compare.includes(c.id)" @click="toggleCompare(c.id)">{{compare.includes(c.id)?'移出对比':'加入对比'}}</button><button class="btn" :disabled="store.saving||!!used(c)" @click="status(c,c.status==='KEPT'?'PENDING':'KEPT')">{{c.status==='KEPT'?'取消保留':'保留'}}</button><button class="btn" :disabled="store.saving||!!used(c)" @click="status(c,c.status==='REJECTED'?'PENDING':'REJECTED')">{{c.status==='REJECTED'?'恢复候选':'淘汰'}}</button><button class="btn primary" :disabled="store.saving||c.status==='REJECTED'" @click="requestAdopt(c)">选择采用范围</button></div></div></article></div>
    <div v-if="!candidates.length" class="empty-state"><Icon name="Images" :size="36"/><h3>为这幅画面积累选择</h3><p>新建图片或视频批次，导入候选后进行比较。</p></div>
    <section v-if="needPlacements.length" class="placement-section"><h3>此需求的采用决定</h3><article v-for="p in needPlacements" :key="p.id" class="placement-row" :data-placement-id="p.id"><div class="placement-preview"><VisualPreview v-if="candidate(p)" :src="urls[p.candidateId]??''" :kind="candidate(p)!.mediaKind" :label="'采用片段 '+location(p)" :start-ms="p.sourceInMs" :end-ms="p.sourceOutMs"/></div><div><b>{{location(p)}}</b><p>{{candidate(p)?asset(candidate(p)!)?.name:''}}<span v-if="p.sourceInMs!==undefined"> · 取素材 {{seconds(p.sourceInMs)}}–{{seconds(p.sourceOutMs)}} 秒</span></p><p>{{p.reason}}</p><button class="text-link" @click="requestAdopt(candidate(p)!,p)">调整范围</button><button class="text-link danger-text" @click="requestRemove(p)">撤销采用</button></div></article></section>
    <details v-if="history.length" class="adoption-history"><summary>采用历史 · {{history.length}} 条</summary><article v-for="p in history" :key="p.id"><b>{{p.active?'使用中':p.supersededBy?'已替换':'已撤销'}} · {{location(p)}}</b><p>{{p.reason}}</p><p v-if="p.removeReason">撤销原因：{{p.removeReason}}</p></article></details>
   </section><section v-else class="empty-state"><Icon name="Images" :size="40"/><h2>从你想改善的画面开始</h2><p>例如人物表情、开场氛围，或成片第 12～15 秒。</p></section>
  </div>
  <section v-if="activePlacements.length" class="project-plan"><div class="section-heading"><div><h2>作品画面采用方案</h2><p>已记录素材与区间，尚未渲染为新成片。</p></div><button class="btn" @click="exportPlan"><Icon name="Download"/>导出采用方案</button></div><div class="plan-scroll"><table><thead><tr><th>画面需求</th><th>采用位置 / 用途</th><th>素材范围</th><th>候选</th></tr></thead><tbody><tr v-for="p in activePlacements" :key="p.id"><td>{{workbench.needs.find(n=>n.id===p.needId)?.title}}</td><td>{{location(p)}}</td><td>{{p.sourceInMs===undefined?'图片':seconds(p.sourceInMs)+'–'+seconds(p.sourceOutMs)+' 秒'}}</td><td>{{candidate(p)?asset(candidate(p)!)?.name:''}}</td></tr></tbody></table></div></section>
  <details v-if="workbench.legacyAdoptions.length" class="adoption-history"><summary>旧版整段采用归档 · {{workbench.legacyAdoptions.length}} 条</summary><pre>{{JSON.stringify(workbench.legacyAdoptions,null,2)}}</pre></details>
 </template>
 <Dialog :open="needOpen" :title="editingNeed?'编辑画面需求':'新建画面需求'" @close="needOpen=false"><form class="form-stack" @submit.prevent="saveNeed"><label>画面需求名称<input v-model="title" required maxlength="120" placeholder="例如：第 12 秒的人物表情"></label><label>画面描述<textarea v-model="description" maxlength="10000" rows="3"/></label><label class="checkbox-label"><input v-model="hasRange" type="checkbox">已确定成片中的目标时间范围</label><div v-if="hasRange" class="form-row"><label>目标起点（秒）<input v-model.number="desiredStart" type="number" min="0" step="0.001" required></label><label>目标终点（秒）<input v-model.number="desiredEnd" type="number" min="0.001" step="0.001" required></label></div><label>所属制作任务<select v-model="productionNodeId" aria-label="所属制作任务"><option value="N27">主体内容 · N27</option><option value="N29">辅助画面 · N29</option></select></label><label>分镜编号（可选）<input v-model="shotId" maxlength="100" placeholder="不按分镜组织时留空"></label><div class="dialog-actions"><button class="btn primary" :disabled="store.saving">保存画面需求</button></div></form></Dialog>
 <Dialog :open="batchOpen" title="新建候选批次" @close="batchOpen=false"><form class="form-stack" @submit.prevent="saveBatch"><label>候选类型<select v-model="batchKind" aria-label="候选类型"><option value="VIDEO">视频片段</option><option value="IMAGE">图片 / 参考帧</option></select></label><label>提示词<textarea v-model="prompt" required maxlength="10000" rows="3"/></label><label>登记的生成模型<select v-model="modelId" aria-label="登记的生成模型"><option value="">填写外部模型</option><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label v-if="!modelId">外部模型名称与版本<input v-model="externalModel" required maxlength="200"></label><label v-if="batchKind==='VIDEO'">视频参考图（可选）<select v-model="referenceId" aria-label="视频参考图"><option value="">直接文生视频</option><option v-for="c in referenceCandidates" :key="c.id" :value="c.id">{{asset(c)?.name}}</option></select></label><label v-if="referenceId">参考图用途<select v-model="referenceRoleForBatch" aria-label="参考图用途"><option value="FIRST_FRAME">首帧</option><option value="LAST_FRAME">尾帧</option><option value="CHARACTER">人物</option><option value="STYLE">风格</option></select></label><label>生成参数（JSON）<textarea v-model="parameters" rows="3" spellcheck="false"/><small>仅记录生成选项，请勿填入密钥或认证头。</small></label><label>批次登记费用上限（元）<input v-model.number="budget" type="number" min="0" step="0.01" required><small>约束人工登记费用，不代表供应商侧扣费上限。</small></label><div class="dialog-actions"><button class="btn primary" :disabled="store.saving">保存批次</button></div></form></Dialog>
 <Dialog :open="importOpen" title="导入画面候选" wide @close="()=>{if(!busy)importOpen=false}"><form class="form-stack" @submit.prevent="importFiles"><label>导入到批次<select v-model="importBatchId" :disabled="busy" aria-label="导入到批次"><option v-for="(b,i) in batches" :key="b.id" :value="b.id">第 {{batches.length-i}} 批 · {{b.mediaKind==='IMAGE'?'图片':'视频'}} · {{b.modelSnapshot.name}}</option></select></label><div class="form-row"><label>seed<input v-model="seed" aria-label="seed" maxlength="100" :disabled="busy"></label><label>每条候选登记费用（元）<input v-model.number="cost" type="number" min="0" step="0.01" required :disabled="busy"></label></div><label>备注<input v-model="note" maxlength="2000" :disabled="busy"></label><label>选择候选文件<input type="file" :accept="importBatch?.mediaKind==='IMAGE'?'.png,.jpg,.jpeg,.webp':'.mp4,.webm'" multiple :disabled="busy" @change="pickFiles"><small>单文件不超过 50MB；批量登记的 seed 和费用会应用于所选文件。</small></label><div v-if="results.length" class="import-results" role="status"><p v-for="(line,i) in results" :key="i">{{line}}</p></div><div class="dialog-actions"><button class="btn" type="button" :disabled="busy" @click="importOpen=false">关闭</button><button class="btn primary" :disabled="busy||store.saving||!files.length">{{busy?'正在导入…':'上传并登记候选'}}</button></div></form><details class="existing-assets"><summary>从本作品素材库登记</summary><label>候选素材<select v-model="libraryAssetId" aria-label="候选素材"><option value="">选择现有素材</option><option v-for="a in libraryAssets" :key="a.id" :value="a.id">{{a.name}}</option></select></label><button class="btn" :disabled="busy||store.saving||!libraryAssetId" @click="importExisting">登记现有素材</button></details></Dialog>
 <Dialog :open="adoptOpen" title="选择采用范围" wide @close="adoptOpen=false"><form v-if="adoption" class="form-stack" @submit.prevent="adopt"><VisualPreview :src="urls[adoption.id]??''" :kind="adoption.mediaKind" :label="'片段预览'" :start-ms="Math.round(sourceIn*1000)" :end-ms="sourceOut>sourceIn?Math.round(sourceOut*1000):undefined" @metadata="ms=>metadata(adoption!.id,ms)"/><label>采用用途<select v-model="purpose" aria-label="采用用途"><option value="TIMELINE">用于成片的一段画面</option><option value="REFERENCE">参考图 / 参考片段</option></select></label><label v-if="needPlacements.length">替换现有采用（可选）<select v-model="replacesId" aria-label="替换现有采用" @change="replacement"><option value="">新增采用，保留其他区间</option><option v-for="p in needPlacements" :key="p.id" :value="p.id">{{location(p)}}</option></select></label><template v-if="adoption.mediaKind==='VIDEO'"><label>素材总时长（秒）<input v-model.number="sourceDuration" type="number" min="0.001" step="0.001" required :readonly="!!adoption.durationMs"><small>浏览器读取；无法读取时请核对原件后填写。</small></label><div class="form-row"><label>素材入点（秒）<input v-model.number="sourceIn" type="number" min="0" step="0.001" required></label><label>素材出点（秒）<input v-model.number="sourceOut" type="number" min="0.001" step="0.001" required></label></div></template><template v-if="purpose==='TIMELINE'"><div class="form-row"><label>成片起点（秒）<input v-model.number="targetStart" type="number" min="0" step="0.001" required></label><label>成片终点（秒）<input v-model.number="targetEnd" type="number" min="0.001" step="0.001" required :readonly="adoption.mediaKind==='VIDEO'"></label></div><label>画面轨道<input v-model="trackId" required pattern="[A-Za-z0-9_-]+" maxlength="100" placeholder="V1"><small>视频按原速采用；同一轨道不可重叠。叠加画面可使用 V2 等其他轨道。</small></label></template><label v-else>参考用途<select v-model="referenceRole" aria-label="参考用途"><option v-for="(name,key) in referenceNames" :key="key" :value="key">{{name}}</option></select></label><label>采用原因<textarea v-model="reason" required maxlength="2000" rows="2"/></label><p class="small">这里只记录采用方案，不直接渲染成片，也不会完成制作步骤。所属制作任务及已交接使用此画面的剪辑步骤会需复查。</p><div class="dialog-actions"><button class="btn" type="button" @click="adoptOpen=false">取消</button><button class="btn primary" :disabled="store.saving">确认采用</button></div></form></Dialog>
 <Dialog :open="removeOpen" title="撤销这条采用决定" @close="removeOpen=false"><form class="form-stack" @submit.prevent="removePlacement"><p>撤销后保留原件和完整历史，相关使用步骤可能需要复查。</p><label>撤销原因<textarea v-model="removeReason" required maxlength="2000" rows="2"/></label><div class="dialog-actions"><button class="btn primary" :disabled="store.saving">确认撤销</button></div></form></Dialog>
</div></template>

